<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/db.php'; require_once __DIR__ . '/../config/paymongo.php'; require_once __DIR__ . '/../includes/auth.php'; requireLogin(); header('Content-Type: application/json');
$input = json_decode((string) file_get_contents('php://input'), true) ?: []; verifyCsrf($input['csrf_token'] ?? null); $invoiceId = filter_var($input['invoice_id'] ?? null, FILTER_VALIDATE_INT); $user = currentUser();
$stmt = $pdo->prepare("SELECT * FROM invoices WHERE id = :id AND tenant_id = :tenant_id AND status IN ('unpaid','overdue') LIMIT 1"); $stmt->execute([':id'=>$invoiceId, ':tenant_id'=>$user['id']]); $invoice = $stmt->fetch(); if (!$invoice) { http_response_code(404); echo json_encode(['error'=>'Invoice is unavailable.']); exit; }
$key = function_exists('paymongoSecretKey') ? paymongoSecretKey() : (string) PAYMONGO_SECRET_KEY; if ($key === '' || str_contains($key, 'change_me')) { http_response_code(503); echo json_encode(['error'=>'PayMongo is not configured.']); exit; }
$payload = ['data'=>['attributes'=>['line_items'=>[['currency'=>'PHP','amount'=>(int) round((float)$invoice['total_amount']*100),'name'=>'Dormitory rent ' . $invoice['month_year'],'quantity'=>1]],'payment_method_types'=>['gcash'],'success_url'=>'http://' . ($_SERVER['HTTP_HOST'] ?? 'localhost') . '/Dormitory/payment_success.php?invoice_id=' . $invoiceId,'cancel_url'=>'http://' . ($_SERVER['HTTP_HOST'] ?? 'localhost') . '/Dormitory/payment_cancel.php','description'=>'Dormitory invoice ' . $invoice['month_year']]]]; $curl = curl_init('https://api.paymongo.com/v1/checkout_sessions'); curl_setopt_array($curl,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Basic ' . base64_encode($key . ':')],CURLOPT_POSTFIELDS=>json_encode($payload)]); $response = curl_exec($curl); $status = curl_getinfo($curl, CURLINFO_HTTP_CODE); curl_close($curl); $data = json_decode((string)$response, true); $checkout = $data['data']['attributes']['checkout_url'] ?? null; if ($status >= 300 || !$checkout) { http_response_code(502); echo json_encode(['error'=>'PayMongo checkout could not be created.']); exit; }
$stmt = $pdo->prepare("INSERT INTO payments (invoice_id, tenant_id, payment_method, amount, paymongo_checkout_id, status) VALUES (:invoice_id,:tenant_id,'gcash_api',:amount,:checkout_id,'pending')"); $stmt->execute([':invoice_id'=>$invoiceId,':tenant_id'=>$user['id'],':amount'=>$invoice['total_amount'],':checkout_id'=>$data['data']['id'] ?? null]); echo json_encode(['checkout_url'=>$checkout]);